const DAWNCREST_DECKS=[{"id": "dawncrest_felines", "name": "Companhia Felina", "strategy": "swift", "ids": ["feline_swordsman", "feline_rogue", "feline_fighter", "feline_arcanist", "feline_drummer", "elf_guardian", "elf_archer", "woodland_lancer"]}, {"id": "dawncrest_sentinels", "name": "Sentinelas da Aurora", "strategy": "fortress", "ids": ["elf_guardian", "elf_halberdier", "elf_archer", "elf_noble", "centaur_lancer", "centaur_crossbow", "feline_arcanist", "flower_fairy"]}, {"id": "dawncrest_woodlands", "name": "Patrulha Silvestre", "strategy": "blades", "ids": ["woodland_predator", "woodland_lancer", "woodland_scout", "woodland_flailer", "centaur_swordsman", "centaur_crossbow", "flower_fairy", "feline_drummer"]}, {"id": "dawncrest_boss", "name": "Corte do Alvorecer", "strategy": "arcane", "ids": ["elf_harpist", "elf_guardian", "centaur_lancer", "elf_noble", "feline_arcanist", "woodland_predator", "elf_archer", "elf_halberdier"]}];
