function configureBlackfangMap(map,seed){const order=shuffle(BLACKFANG_DECKS.slice(0,3).map(d=>d.id),rng(seed^0x26bf));for(const [i,layer] of [4,9].entries()){const n=map[layer].find(n=>n.lane===1);Object.assign(n,{type:'elite',campaign:'blackfang',forceId:order[i],name:'Blackfang'});for(const p of map[layer-1])for(const choice of map[layer])if(!p.links.includes(choice.id))p.links.push(choice.id);}const dawn=shuffle(DAWNCREST_DECKS.slice(0,3).map(d=>d.id),rng(seed^0x37dc));for(const [i,layer] of [4,9].entries())Object.assign(map[layer].find(n=>n.lane===2),{type:'elite',campaign:'dawncrest',forceId:dawn[i],name:'Dawncrest'});const monsters=shuffle(['tree','colossus','slime','dragon','hydra','kraken','lich','naga','manticore'],rng(seed^0x42aa));for(const [i,layer]of[4,9].entries())Object.assign(map[layer].find(n=>n.lane===0),{type:'elite',campaign:'monsters',raidKind:monsters[i],forceId:'monster_'+monsters[i],name:'Raid'});return map;}
function playedMonsterKinds(s){const ids=new Set([...(s.route||[]),...(s.campaignRoute?.monsterNodes||[])]);return new Set([...(root.JourneyActs?.played(s)||[]),...(s.map.flat().filter(n=>n.campaign==='monsters'&&n.type!=='boss'&&ids.has(n.id)).map(n=>n.raidKind||'tree'))]);}
function prepareRouteNode(s,n){if(n.type==='boss'&&s.route?.includes(n.id))return n;const r=s.campaignRoute;if(!r)return n;const used=playedMonsterKinds(s),pool=['tree','colossus','slime','dragon','hydra','kraken','lich','naga','manticore'].filter(id=>!used.has(id));
 if(n.campaign==='monsters'&&n.type!=='boss'&&!s.route.includes(n.id)&&used.has(n.raidKind)&&pool.length){const id=pool[Math.floor(rng(s.seed^0x43cc^n.layer)()*pool.length)];Object.assign(n,{raidKind:id,forceId:'monster_'+id});Object.assign(s.map[n.layer].find(v=>v.id===n.id),n);}
 if(n.type==='boss'){if((r.monsterNodes||[]).length>=2){if(!pool.includes(r.monsterBoss))r.monsterBoss=pool[Math.floor(rng(s.seed^0x42bb)()*pool.length)];Object.assign(n,{campaign:'monsters',raidKind:r.monsterBoss,forceId:'monster_boss_'+r.monsterBoss,name:'Raid'});r.boss=n.forceId;Object.assign(s.map[n.layer].find(v=>v.id===n.id),n);root.JourneyActs?.prepareBoss(s,n);return n;}const dawn=(r.dawncrestForces||[]).length>=2,black=(r.defeatedForces||[]).length>=2;if(dawn||black){Object.assign(n,{campaign:dawn?'dawncrest':'blackfang',forceId:dawn?'dawncrest_boss':'blackfang_boss',name:dawn?'Harpista Alta Elfa':'Rei Goblin'});r.boss=n.forceId;const saved=s.map[n.layer].find(v=>v.id===n.id);Object.assign(saved,n);}else{Object.assign(n,{campaign:'ironbound',forceId:'ironbound_boss',name:'Ironbound'});r.boss=n.forceId;Object.assign(s.map[n.layer].find(v=>v.id===n.id),n);}}root.JourneyActs?.prepareBoss(s,n);return n;}
function routeVictory(s){if(!s.tutorialReplay&&s.campaignRoute&&s.current?.campaign==='monsters'){const r=s.campaignRoute;if(s.current.type==='boss'){r.bossDefeated=true;return;}r.monsterNodes??=[];if(!r.monsterNodes.includes(s.current.id))r.monsterNodes.push(s.current.id);if(r.monsterNodes.length>=2)prepareRouteNode(s,s.map[14][0]);return;}if(s.tutorialReplay||!s.campaignRoute||!['blackfang','dawncrest'].includes(s.current?.campaign)||s.eventEncounter)return;const r=s.campaignRoute;if(s.current.type==='boss'){r.bossDefeated=true;return;}const dawn=s.current.campaign==='dawncrest',forces=dawn?(r.dawncrestForces??=[]):r.defeatedForces,nodes=dawn?(r.dawncrestNodes??=[]):r.wonNodes;if(s.current.type!=='elite'||nodes.includes(s.current.id))return;nodes.push(s.current.id);if(!forces.includes(s.current.forceId))forces.push(s.current.forceId);if(forces.length>=2)prepareRouteNode(s,s.map[14][0]);}
function runCardAvailable(s,id){const u=BY[id];if(u?.bossCard&&!(s.bossCardsAvailable||[]).includes(id))return false;return !!u&&!u.enemyOnly&&(!u.order||u.order==='ironbound'||u.order==='blackfang'&&s.blackfangAvailable||u.order==='dawncrest'&&s.dawncrestAvailable);}

function generateMap(seed=1){const r=rng(seed^0x752c43),battles=new Set([0,2,4,5,7,9,10,12,14]),dev=[1,3,6,8,11,13];let map=[];for(let layer=0;layer<15;layer++){let lanes=layer===0||layer===14?[1]:[0,1,2];map.push(lanes.map(lane=>{let type;if(layer===14)type='boss';else if(battles.has(layer))type=layer>2&&((layer+lane+seed)%4===0)?'elite':'battle';else{let options=[['recruit','upgrade','event'],['shop','event','relic'],['upgrade','relic','shop'],['event','recruit','upgrade'],['relic','shop','event'],['upgrade','shop','relic']][dev.indexOf(layer)];type=options[(lane+(seed%3))%3];}let id=layer===0?'c1':layer===14?'boss':'n'+layer+'_'+lane;let eventId=EVENTS[Math.floor(r()*EVENTS.length)].id;return{id,type,layer,lane,x:lanes.length===1?.5:[.17,.50,.83][lane]+(r()-.5)*.05,name:({battle:'Confronto',elite:'Companhia de elite',boss:'Guardião da passagem',recruit:'Caravana',upgrade:'Santuário de treino',event:EVENT_BY[eventId].name,shop:'Mercado da estrada',relic:'Relicário'})[type],eventId,links:[]};}));}
for(let i=0;i<14;i++)for(let n of map[i]){let next=map[i+1];if(next.length===1||i===0)n.links=next.map(t=>t.id);else{n.links=next.filter(t=>t.lane===n.lane).map(t=>t.id);if([2,5,8,11].includes(i)){let adjacent=n.lane===0?1:n.lane===2?1:(Math.floor(r()*2)?2:0);n.links.push(next.find(t=>t.lane===adjacent).id);}}}const configured=configureBlackfangMap(map,seed);return root.JourneyMaps?.arrange(configured,seed,1)||configured;}
const MAP=generateMap(1);
function isFight(n){return ['battle','elite','boss'].includes(n.type);}
function battleReward(stage){return [14,16,18][Math.min(3,Math.ceil(stage/9))-1];}
function ownedRelics(s){return [...s.artifacts,...(s.reserve||[])];}
function takeRelic(s,id){s.artifacts=s.artifacts.filter(x=>x!==id);s.reserve=(s.reserve||[]).filter(x=>x!==id);ensureBag(s);return id;}
function eventViable(s,e){const eligible=s.cards.filter(c=>c.level<2);if(e.relicChance&&!unownedRelics(s).length)return false;return s.gold>=Math.max(e.cost||0,e.minGold||0)&&(!(e.relic||e.hasRelic)||ownedRelics(s).length>0)&&(!e.card||s.cards.length>1)&&(!e.upgradeCard||eligible.length>0)&&(!e.targets||eligible.length>=2&&s.cards.length>=3)&&(!(e.cards||['resgate','mercador','contrabando','ataque'].includes(e.id))||UNITS.some(u=>copies(s,u.id)<MAX_COPIES));}
