function announce(b,u,label){b.effects.push({kind:'ring',x:u.x,y:u.y,color:'#eed28a',life:.5,full:.5});floating(b,{x:u.x,y:u.y-24},label||BY[u.type].ability.toUpperCase(),label?'#b6ddff':'#f5d28d',false);if(label==='BLOQUEIO')visualCue(b,'block',.5);}
