 n=root.JourneyBosses?.modifyHit(b,a,t,n,skill,options)??n;n=root.JourneyTree?.hit(b,a,t,n,skill,options)??n;
 if(!root.JourneyTraits&&basicReceived&&!skill&&!options.dot){addCharge(t,'received');t.lastAggressor=a.uid;}
 n=root.JourneyTraits?.damage(b,a,t,n,skill,options)??n;const crit=options.crit===true||(!skill&&b.random()<(root.JourneyTraits?.crit(b,a,a.crit||0)??(a.crit||0)));
 let ignore=root.JourneyTree?.ignore(b,a,skill,options.ignore||0,crit)??(options.ignore||0);ignore=root.JourneyTraits?.ignore(b,a,t,skill,ignore)??ignore;let defense=(root.JourneyTraits?.defense(b,t,t.defense||0)??(t.defense||0))*(t.guardBreak>0?.75:t.breakTime>0?.8:1)*(1-ignore);
