 reduction=root.JourneyTraits?.reduction(b,t,reduction)??reduction;const outgoing=(combatHas(b,a.side,'execution')&&t.hp/t.maxhp<.3?1+RT.execution:1)*(1+(combatHas(b,a.side,'ember')?(b.embers[a.side]||0)*RT.emberAtk:0));
 const v=n*(t.raidDamageTaken??1)*(1+bonus(a,'atk'))*(skill&&a.royalTime>0?1+(a.royalPower||0):1)*outgoing*(!skill&&t.preyMark>0?1.15:1)*(a.atkDown>0?.8:1)*(crit?1.5*(a.treeCritDamage?1+a.treeCritDamage:1):1)*(!b.raid&&b.time>=40?5:1)*(100/(100+defense))*(1-reduction);
