 if(!a.raidBoss&&!options.dot){a.attackVisualUntil=b.time+.24;a.attackTarget=t.uid;}if(!a.raidBoss)b.effects.push({targetRaid:!!t.raidBoss,kind:BY[a.type].range>100?'projectile':'slash',weapon:weaponKind(a.type),type:a.type,crit,skill,x:a.x,y:a.y-25,tx:t.x,ty:t.y-(t.raidBoss?70:10),color:skill?'#efd48b':BY[a.type].color,life:skill?.46:.32,full:skill?.46:.32});
