function moveUnit(b,u,p,forced=false,teleport=false,maxTravel=Infinity){if(u.raidBoss||(b.raid&&u.root>0&&!forced))return false;if(forced&&u.protectTime>0)return false;const q=safePoint(b,u,p,maxTravel);root.JourneyTree?.moved(b,u,forced);if(teleport){b.effects.push({kind:'teleport',x:u.x,y:u.y,color:'#a8bfff',life:.3,full:.3});u.x=q.x;u.y=q.y;u.motion=null;b.effects.push({kind:'teleport',x:u.x,y:u.y,color:'#a8bfff',life:.4,full:.4});}else{b.effects.push({kind:'dash',x:u.x,y:u.y,tx:q.x,ty:q.y,life:.24,full:.24});u.motion={x:q.x,y:q.y,life:.18};}return true;}
function pushUnit(b,origin,t,d){let dir=direction(origin,t);moveUnit(b,t,{x:t.x+dir.x*d,y:t.y+dir.y*d},true);}
function lineTargets(u,target,targets,length,width=22){const d=direction(u,target);return targets.filter(t=>{let dx=t.x-u.x,dy=t.y-u.y,along=dx*d.x+dy*d.y;return along>=0&&along<=length&&Math.abs(dx*d.y-dy*d.x)<=width;});}
